export function crop(image,index,cols=4,rows=2){if(image.src?.includes('office-environment')){const xs=[0,412,820,1220,1536],ys=[0,380,704,1024],col=index%4,row=Math.floor(index/4);return {x:xs[col]/1536*image.naturalWidth,y:ys[row]/1024*image.naturalHeight,width:(xs[col+1]-xs[col])/1536*image.naturalWidth,height:(ys[row+1]-ys[row])/1024*image.naturalHeight};}return {x:(index%cols)*image.naturalWidth/cols,y:Math.floor(index/cols)*image.naturalHeight/rows,width:image.naturalWidth/cols,height:image.naturalHeight/rows};}
export function blit(ctx,img,index,x,y,w,h,cols=4,rows=2){const r=crop(img,index,cols,rows);ctx.drawImage(img,r.x,r.y,r.width,r.height,x,y,w,h);}
function text(c,s,x,y,size=12,color='#38532c'){c.font=`bold ${size}px system-ui,sans-serif`;c.fillStyle=color;c.textAlign='center';c.fillText(s,x,y);}
function round(c,x,y,w,h,r,color){c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=color;c.fill();}
function distanceToSegment(p,a,b){const dx=b[0]-a[0],dy=b[1]-a[1];const t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)));return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy);}
