 const entry=route[0],end=route.at(-1);const entryX=this.portrait?Math.max(5,entry[0]-50):2,entryY=this.portrait?3:entry[1]-96,baseX=this.portrait?Math.max(0,Math.min(this.W-108,end[0]-54)):this.W-108,baseY=this.portrait?this.H-132:end[1]-113;
