 for(let i=0;i<(office?500:900)&&dressing.length<(office?32:60);i++){const x=((Math.sin(i*91.73+game.level)*43758.54)%1+1)%1*(this.W+30)-15,y=((Math.sin(i*41.17+7)*9643.37)%1+1)%1*(this.H+30)-10,index=office?[1,2,10,1,3,11,1,2,7,10,0][i%11]:[0,1,0,2,1,3,0,2,7,10,11][i%11],size=index===0?72:index===1?80:54,box={x:x-size/2,y:y-size*.9,w:size,h:size};if(box.x<0||box.x+box.w>this.W||box.y<0||box.y+box.h>this.H||occupied.some(b=>overlaps(box,b))||roads.some(b=>overlaps(box,b,3)))continue;occupied.push(box);dressing.push({index,size,box});}
