 for(let i=0;i<game.map.slots.length;i++){const[x,y]=this.point(...game.map.slots[i]);if(!s.towers.some(t=>t.slot===i)){blit(c,this.environment,8,x-41,y-32,82,65,4,3);text(c,String(i+1).padStart(2,'0'),x,y+34,9,'#375035');}}
 const selected=game.tower||(game.selectedSlot>=0?{slot:game.selectedSlot,type:game.selectedType,level:0,branch:null}:null);if(selected){const[x,y]=this.point(...game.map.slots[selected.slot]),r=selected.branch==='manager'&&selected.type===0?(selected.level===4?220:175):game.range(selected);if(r){const color=selected.branch==='manager'?'#e2b752':TYPES[selected.type].color;this.rangeField(x,y,r,color);if(!(selected.branch==='manager'&&selected.type===0)){c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();c.beginPath();game.map.route.forEach((point,i)=>{const p=this.point(...point);i?c.lineTo(...p):c.moveTo(...p);});c.strokeStyle=color+'b0';c.lineWidth=6;c.lineCap='round';c.shadowColor=color;c.shadowBlur=9;c.stroke();c.restore();}}}
