 for(const original of s.effects){const p=this.point(original.x,original.y),target=this.point(original.tx,original.ty),f={...original,x:p[0],y:p[1],tx:original.tx===undefined?undefined:target[0],ty:target[1]};if(f.job!==undefined){if(original.slot!==undefined){const source=this.point(...game.map.slots[original.slot]);f.x=source[0];f.y=source[1]-45;}if(f.tx!==undefined)f.ty-=14;else if(f.blast)f.y-=14;drawAttack(c,f,matchMedia('(prefers-reduced-motion: reduce)').matches);continue;}c.globalAlpha=Math.max(0,f.life/f.max);if(f.tx!==undefined){c.beginPath();c.moveTo(f.x,f.y);c.lineTo(f.tx,f.ty);c.strokeStyle=f.color;c.shadowColor=f.color;c.shadowBlur=7;c.lineWidth=4;c.stroke();c.shadowBlur=0;round(c,f.tx-4,f.ty-4,8,8,4,'#fff9bc');}else if(f.text)text(c,f.text,f.x,f.y-(1-f.life/f.max)*26,16,f.color);else{c.beginPath();c.arc(f.x,f.y,(f.radius||20)*(1-f.life/f.max),0,Math.PI*2);c.strokeStyle=f.color;c.lineWidth=4;c.stroke();}c.globalAlpha=1;}
